import json,sys
from collections import defaultdict
d=json.load(sys.stdin)
items={i['id']:i for i in d['items']}
kids=defaultdict(list)
for i in d['items']:
    p=i.get('parent')
    if p: kids[p].append(i['id'])
open_st={'pending','active','blocked'}
for pid,ch in kids.items():
    p=items.get(pid)
    if not p: 
        print('MISSING PARENT', pid, '<-', ch); continue
    st=[items[c]['status'] for c in ch]
    if p['status'] in open_st and all(s in ('done','rejected','cancelled') for s in st):
        print('PARENT OPEN, ALL CHILDREN CLOSED:', pid, p['status'], '|', [(c,items[c]['status']) for c in ch])
    if p['status']=='done' and any(s in open_st for s in st):
        print('PARENT DONE, OPEN CHILDREN:', pid, '|', [(c,items[c]['status']) for c in ch if items[c]['status'] in open_st])
print('--- milestones active ---')
ms=defaultdict(set)
for i in d['items']:
    if i.get('milestone'): ms[i['milestone']].add(i['status'])
for k,v in ms.items(): print(k,sorted(v))
print('--- orphan parents (parent id not in items) ---')
for i in d['items']:
    if i.get('parent') and i['parent'] not in items: print(i['id'],'->',i['parent'])
